import sys
fn branch(flag: bool) -> i64 {
  var pipe = sys.Pipe(2147483642, 2147483643)
  defer {
    if (flag) { pipe.closeRead() } else { pipe.closeWrite() }
    pipe.closeRead()
    pipe.closeWrite()
  }
  var primed = pipe.closeRead()
  if (primed) {
    Coro.yield()
    return 43
  }
  return 42
}
fn answer() -> i64 {
  return branch(true) + branch(false)
}

