  var inner = sys.Pipe(2147483638, 2147483639)
  defer {
    var choose = flag
    defer {
      if (choose) { inner.closeRead() } else { inner.closeWrite() }
      inner.closeRead()
      inner.closeWrite()
    }
    outer.closeRead()
    outer.closeWrite()
  }
  var primed = outer.closeRead()
  if (primed) {
    Coro.yield()
    return 42
  }
  return 41
}
